MAGIC_NUMBER = 0x4455434B # DUCK
MAGIC_SIZE = 4

CONFIG_OVERRIDE_OP_READ = 1
CONFIG_OVERRIDE_OP_WRITE = 2
CONFIG_OVERRIDE_OP_DELETE = 3
CONFIG_OVERRIDE_CHUNK_SIZE = 512

class API:
    def __init__(
        self,
        serial_port: str = "/dev/puddleduck_ctrl"
    ):
        self.ser = serial.Serial(serial_port, timeout=1.0)
        self.commandWrapper = command_pb2.CommandWrapper()
        self.responseWrapper = response_pb2.ResponseWrapper()

    def drain_read_buffer(self):
        """
        Read (and discard) until the serial input buffer is empty.
        """
        if hasattr(self.ser, 'reset_input_buffer'):
            self.ser.reset_input_buffer()
        elif hasattr(self.ser, 'flushInput'):
            self.ser.flushInput()

        # As a fallback (or to be extra sure), consume any leftover bytes:
        while True:
            # get count of waiting bytes
            try:
                count = self.ser.in_waiting
            except AttributeError:
                count = self.ser.inWaiting()
            if count <= 0:
                break
            # read & discard them
            self.ser.read(count)

    def send_message(self,message_bytes):
        """
        Send a binary protobuf message with a magic header and a CRC appended.
        
        Packet format:
          [4-byte MAGIC][4-byte total length (payload+4)][payload][4-byte CRC32]
        """
        # Compute the CRC32 over the payload (message_bytes is a bytes object)
        crc = zlib.crc32(message_bytes) & 0xffffffff
        total_len = len(message_bytes) + 4  # payload + 4-byte CRC
        # Pack magic number and total length in big-endian format.
        magic_bytes = MAGIC_NUMBER.to_bytes(4, byteorder='big')
        total_len_bytes = total_len.to_bytes(4, byteorder='big')
        crc_bytes = struct.pack(">I", crc)
        # Build the full packet.
        packet = magic_bytes + total_len_bytes + message_bytes + crc_bytes
        self.ser.write(packet)
        self.ser.flush()

    def policyStart(self, name="default", dt=0):
        start_msg = policy_start_pb2.PolicyStart()
        start_msg.name = name
        start_msg.dt = dt
        self.commandWrapper.Clear()
        self.commandWrapper.policy_start.CopyFrom(start_msg)
        self.send_message(self.commandWrapper.SerializeToString())

    def policyAction(self, name, joint_radians, joint_kds=None, joint_kps=None, duration=0):
        action_msg = policy_action_pb2.PolicyAction()
        action_msg.name = name
        action_msg.duration = duration
        action_msg.joint_radians[:] = joint_radians
        if joint_kds is not None:
            action_msg.joint_kds[:] = joint_kds
        if joint_kps is not None:
            action_msg.joint_kps[:] = joint_kps
        self.commandWrapper.Clear()
        self.commandWrapper.policy_action.CopyFrom(action_msg)
        self.send_message(self.commandWrapper.SerializeToString())

