    @staticmethod
    def _dynamixel_tuning_values(msg):
        if msg is None:
            return {
                'position_p_gain': None,
                'position_i_gain': None,
                'position_d_gain': None,
                'profile_acceleration': None,
                'profile_velocity': None,
            }
        return {
            field: int(getattr(msg, field))
            if bool(getattr(msg, f'has_{field}')) else None
            for field in (
                'position_p_gain',
                'position_i_gain',
                'position_d_gain',
                'profile_acceleration',
                'profile_velocity',
            )
        }

    def listDynamixelTunings(self, timeout: int = 8):
        """Read live and optional EEPROM-managed tuning for the head Dynamixels."""
        request = motor_registry_pb2.ListDynamixelTunings()
        self.commandWrapper.Clear()
        self.commandWrapper.list_dynamixel_tunings.CopyFrom(request)
        self.send_message(self.commandWrapper.SerializeToString())
        msg = self.waitFor('list_dynamixel_tunings', timeout=timeout)
        if msg is None:
            raise TimeoutError("Timed out waiting for Dynamixel tuning values")
        if not msg.ok:
            raise RuntimeError(msg.message or "Dynamixel tuning read failed")
        return {
            'ok': True,
            'message': msg.message,
            'registry_available': bool(msg.registry_available),
            'limits': {
                'position_gain': int(msg.max_position_gain),
                'profile': int(msg.max_profile_value),
            },
            'actuators': [
                {
                    'name': actuator.name,
                    'motor_id': int(actuator.motor_id),
                    'mode': actuator.mode,
                    'connected': bool(actuator.connected),
                    'current_valid': bool(actuator.current_valid),
                    'current': self._dynamixel_tuning_values(actuator.current),
                    'registry_override': bool(actuator.registry_override),
                    'requested': self._dynamixel_tuning_values(actuator.requested),
                    'requested_matches_current': bool(
                        actuator.requested_matches_current
                    ),
                    'message': actuator.message,
                }
                for actuator in msg.actuators
            ],
        }

    def setDynamixelTuning(self, name: str, values: dict, timeout: int = 10):
        """Persist selected raw fields and apply only values that differ live."""
        if not isinstance(values, dict):
            raise TypeError("values must be a dict")
        request = motor_registry_pb2.SetDynamixelTuning()
        request.name = str(name or '')
        requested = request.requested
        for field in (
            'position_p_gain',
            'position_i_gain',
            'position_d_gain',
            'profile_acceleration',
            'profile_velocity',
        ):
            value = values.get(field)
            if value is None:
                continue
            setattr(requested, f'has_{field}', True)
            setattr(requested, field, int(value))

        self.commandWrapper.Clear()
        self.commandWrapper.set_dynamixel_tuning.CopyFrom(request)
        self.send_message(self.commandWrapper.SerializeToString())
        msg = self.waitFor('set_dynamixel_tuning', timeout=timeout)
        if msg is None:
            raise TimeoutError("Timed out waiting for Dynamixel tuning update")
        if not msg.ok:
            raise RuntimeError(msg.message or "Dynamixel tuning update failed")
        return {
            'ok': True,
            'name': msg.name,
            'requested': self._dynamixel_tuning_values(msg.requested),
            'registry_changed': bool(msg.registry_changed),
            'motor_changed': bool(msg.motor_changed),
            'applied': bool(msg.applied),
            'message': msg.message,
        }

    def clearDynamixelTuning(self, name: str, timeout: int = 8):
        """Stop managing a motor without changing its current control table."""
        request = motor_registry_pb2.ClearDynamixelTuning()
        request.name = str(name or '')
