    def pdplayInline(self, steps, timeout: int = 5):
        """Run an in-memory PDPLAY script.

        Each step is ``(name, radians, duration_ms)``.  A named step starts an
        interpolation and the scheduler immediately advances on its next tick;
        an empty name is an explicit pause for ``duration_ms``.
        """
        pd_play_inline = robot_control_pb2.PdPlayInline()
        for name, radians, duration_ms in steps:
            pd_play_inline.step_name.append(name or '')
            pd_play_inline.step_radians.append(float(radians))
            pd_play_inline.step_duration_ms.append(int(duration_ms))
        self.commandWrapper.Clear()
        self.commandWrapper.pd_play_inline.CopyFrom(pd_play_inline)
        self.send_message(self.commandWrapper.SerializeToString())
        msg = self.waitFor('pd_play_inline', timeout=timeout)
        if msg is None:
            raise TimeoutError("Timed out waiting for pd_play_inline response")
        if not msg.ok:
            raise RuntimeError(msg.message or "Inline PDPLAY failed")
        return msg

