    def runDiagnostics(self, timeout: int = 20):
        """Relax the robot, scan the fixed body motor buses, and return a structured report."""
        request = diagnostics_pb2.RunDiagnostics()
        request.scan_motors = True
        self.commandWrapper.Clear()
        self.commandWrapper.run_diagnostics.CopyFrom(request)
        self.send_message(self.commandWrapper.SerializeToString())
        msg = self.waitFor('run_diagnostics', timeout=timeout)
        if msg is None:
            raise TimeoutError("Timed out waiting for run_diagnostics response")

        return {
            'ok': bool(msg.ok),
            'message': msg.message,
            'diagnostic_mode': bool(msg.diagnostic_mode),
            'robot': msg.robot,
            'options': msg.options,
            'firmware': {
                'version': msg.firmware_version,
                'build': msg.firmware_build,
                'target': msg.firmware_target,
                'config_hash': int(msg.config_hash),
            },
            'buses': [
                {
                    'name': bus.name,
                    'expected_type': bus.expected_type,
                    'adapter': bus.adapter,
                    'baud': int(bus.baud),
                    'configured': bool(bus.configured),
                    'scanned': bool(bus.scanned),
                    'ok': bool(bus.ok),
                    'message': bus.message,
                    'detected_ids': [int(value) for value in bus.detected_ids],
                    'unassigned_ids': [int(value) for value in bus.unassigned_ids],
                    'positions': [
                        {
                            'bus': position.bus,
                            'id': int(position.id),
                            'valid': bool(position.valid),
                            'radians': float(position.radians),
                            'message': position.message,
                        }
                        for position in bus.positions
                    ],
                    'motors': [
                        {
                            'name': motor.name,
                            'type': motor.type,
                            'bus': motor.bus,
                            'default_id': int(motor.default_id),
                            'active_id': int(motor.active_id),
                            'detected': bool(motor.detected),
                            'type_matches_bus': bool(motor.type_matches_bus),
                        }
                        for motor in bus.motors
                    ],
                }
                for bus in msg.buses
            ],
            'sensors': [
                {
                    'name': sensor.name,
                    'source': sensor.source,
                    'bus': sensor.bus,
                    'configured': bool(sensor.configured),
                    'present': bool(sensor.present),
                    'version': sensor.version,
                    'message': sensor.message,
                    'timestamp': int(sensor.timestamp),
                }
                for sensor in msg.sensors
            ],
        }

