    @staticmethod
    def _estop_status(msg):
        return {
            'ok': bool(msg.ok),
            'message': msg.message,
            'mode': msg.mode,
            'gpio': int(msg.gpio),
            'sbus_channel': int(msg.sbus_channel),
            'defaults': {
                'mode': msg.default_mode,
                'gpio': int(msg.default_gpio),
                'sbus_channel': int(msg.default_sbus_channel),
            },
            'override_active': bool(msg.override_active),
            'gpio_options': [
                {
                    'pin': int(option.pin),
                    'name': option.name,
                    'default': bool(option.default_pin),
                }
                for option in msg.gpio_options
            ],
            'runtime': {
                'motor_allowed': bool(msg.motor_allowed),
                'estop_active': bool(msg.estop_active),
                'sbus_healthy': bool(msg.sbus_healthy),
                'sbus_value': float(msg.sbus_value),
            },
        }

