    def read_message(self):
        """
        Read a binary message with a magic header, length prefix, and CRC.
        If the stream is out‑of‑sync, resynchronize on MAGIC_NUMBER.
        Returns the payload bytes if valid, or None on timeout/short read.
        """
        # helper to read exactly n bytes or return None
        def _read_n(n):
            data = self.ser.read(n)
            return data if len(data) == n else None

        # continuously scan for the magic signature
        buf = bytearray()
        while True:
            byte = self.ser.read(1)
            if not byte:
                # no data available (timeout)
                return None
            buf += byte
            # keep only the last MAGIC_SIZE bytes
            if len(buf) > MAGIC_SIZE:
                buf.pop(0)
            if len(buf) == MAGIC_SIZE and int.from_bytes(buf, 'big') == MAGIC_NUMBER:
                # found a valid header
                break

        # Next 4 bytes = total length (payload + 4 CRC bytes)
        len_bytes = _read_n(4)
        if len_bytes is None:
            return None
        total_len = int.from_bytes(len_bytes, byteorder='big')
        payload_len = total_len - 4

        # Read payload
        payload = _read_n(payload_len)
        if payload is None:
            return None

        # Read CRC
        crc_bytes = _read_n(4)
        if crc_bytes is None:
            return None
        received_crc = struct.unpack(">I", crc_bytes)[0]

        # Validate CRC
        computed_crc = zlib.crc32(payload) & 0xFFFFFFFF
        if received_crc != computed_crc:
            print(f"[Warning] CRC mismatch (got {received_crc:#010x}, expected {computed_crc:#010x}), resyncing...")
            # drop the first byte of our last MAGIC window to avoid infinite loop on constant stream
            buf.pop(0)
            return None

        # good packet!
        return payload

    def receive(self, blocking: bool = False):
        if not blocking and self.ser.in_waiting == 0:
            return None, None
        data = self.read_message()
        if not data:
            return None, None
        self.responseWrapper.Clear()
        try:
            self.responseWrapper.ParseFromString(data)
        except Exception as e:
            print("Failed to parse response:", e)
            return None, None
        cmd = self.responseWrapper.WhichOneof('command')
        if not cmd:
            return None, None
        return cmd, getattr(self.responseWrapper, cmd)

    def waitFor(self, msg_type: str, timeout: int = 5):
        start_time = time.time()
        while True:
            current_time = time.time()
            elapsed_time = current_time - start_time
            recv_msg_type, msg = self.receive(blocking=(timeout > 0))
            if recv_msg_type == msg_type:
                return msg
            if timeout > 0 and elapsed_time > timeout:
                break
        return None
